-- EcoRecommend AI: isolated private records and trusted administrator roles.
create extension if not exists vector;
create extension if not exists pgcrypto;
create table public.profiles(id uuid primary key references auth.users(id) on delete cascade,display_name text check(length(display_name)<=100),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.roles(user_id uuid primary key references auth.users(id) on delete cascade,role text not null check(role in ('user','admin')) default 'user',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create or replace function public.is_admin() returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.roles where user_id=auth.uid() and role='admin'); $$;
revoke all on function public.is_admin() from public;
grant execute on function public.is_admin() to authenticated,anon;
create table public.categories(id text primary key,name text not null unique,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.products(id text primary key,category text not null references public.categories(name),name text not null,data jsonb not null check(jsonb_typeof(data)='object'),active boolean not null default true,embedding vector(384),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create index products_category_idx on public.products(category);
create index products_search_idx on public.products using gin(to_tsvector('english',name));
create table public.product_images(id uuid primary key default gen_random_uuid(),product_id text not null references public.products(id) on delete cascade,url text not null check(url like 'https://%'),alt text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.product_attributes(id uuid primary key default gen_random_uuid(),product_id text not null references public.products(id) on delete cascade,attribute text not null,value jsonb,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(product_id,attribute));
create table public.sustainability_assessments(id uuid primary key default gen_random_uuid(),product_id text not null references public.products(id) on delete cascade,score numeric check(score between 0 and 100),completeness numeric not null check(completeness between 0 and 100),methodology text not null,raw_attributes jsonb not null,normalized_scores jsonb not null default '{}',confidence text not null,assessed_at timestamptz not null default now(),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.sustainability_sources(id uuid primary key default gen_random_uuid(),product_id text not null references public.products(id) on delete cascade,name text not null,url text,attribute text not null,status text not null check(status in ('verified','manufacturer-reported','estimated','unavailable','demonstration')),retrieved_at timestamptz not null default now(),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.model_versions(id text primary key,data jsonb not null,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
-- User-scoped tables use JSONB for versioned event payloads, not for authorization.
do $$ declare t text; begin foreach t in array array['product_reviews','user_preferences','user_interactions','recommendations','recommendation_explanations','wishlists','carts','cart_items','comparisons','recently_viewed','chat_sessions','chat_messages','audit_logs'] loop execute format('create table public.%I(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,data jsonb not null default ''{}'',created_at timestamptz not null default now(),updated_at timestamptz not null default now())',t); execute format('create index %I on public.%I(user_id,created_at desc)',t||'_owner_idx',t);end loop;end $$;
create table public.wishlist_items(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,product_id text not null references public.products(id) on delete cascade,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(user_id,product_id));
create or replace function public.touch_updated_at() returns trigger language plpgsql set search_path=public as $$begin new.updated_at=now();return new;end$$;
do $$ declare t text; begin for t in select tablename from pg_tables where schemaname='public' and tablename in ('profiles','roles','categories','products','product_images','product_attributes','sustainability_assessments','sustainability_sources','product_reviews','user_preferences','user_interactions','recommendations','recommendation_explanations','wishlists','wishlist_items','carts','cart_items','comparisons','recently_viewed','chat_sessions','chat_messages','model_versions','audit_logs') loop execute format('alter table public.%I enable row level security',t);execute format('create trigger updated_at before update on public.%I for each row execute function public.touch_updated_at()',t); end loop;end$$;
create policy profile_owner on public.profiles for all to authenticated using(id=auth.uid()) with check(id=auth.uid());
create policy profile_admin_read on public.profiles for select to authenticated using(public.is_admin());
create policy role_owner_read on public.roles for select to authenticated using(user_id=auth.uid() or public.is_admin());
-- No role write policies: role promotion requires a trusted SQL/service session.
do $$ declare t text; begin foreach t in array array['categories','products','product_images','product_attributes','sustainability_assessments','sustainability_sources','model_versions'] loop execute format('create policy catalog_read on public.%I for select to anon,authenticated using(true)',t);execute format('create policy catalog_admin_write on public.%I for all to authenticated using(public.is_admin()) with check(public.is_admin())',t);end loop;end$$;
do $$ declare t text; begin foreach t in array array['product_reviews','user_preferences','user_interactions','recommendations','recommendation_explanations','wishlists','wishlist_items','carts','cart_items','comparisons','recently_viewed','chat_sessions','chat_messages'] loop execute format('create policy owner_access on public.%I for all to authenticated using(user_id=auth.uid()) with check(user_id=auth.uid())',t);end loop;end$$;
create policy admin_recommendation_read on public.recommendations for select to authenticated using(public.is_admin());
create policy admin_audit_read on public.audit_logs for select to authenticated using(public.is_admin());
-- Audit logs cannot be changed through the public API.
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$begin insert into public.profiles(id) values(new.id);insert into public.roles(user_id,role) values(new.id,'user');return new;end$$;
create trigger on_auth_user_created after insert on auth.users for each row execute function public.handle_new_user();
